<style>
/* This override applies only when the Seller main contains the Messages inbox. */
#sellerMainContent > main:has(> .seller-inbox){max-width:none}
.seller-inbox{--inbox-height:calc(100dvh - 150px);height:var(--inbox-height);min-height:240px;display:grid;grid-template-columns:340px minmax(0,1fr);overflow:hidden;border:1px solid #dde6e1;border-radius:16px;background:#fff;box-shadow:0 8px 28px #173f3508;color:#24312c}.seller-inbox [hidden]{display:none!important}.seller-inbox h1,.seller-inbox h2,.seller-inbox p{margin:0}.seller-inbox button,.seller-inbox input,.seller-inbox textarea{font:inherit}.seller-inbox button,.seller-inbox a{touch-action:manipulation}.seller-inbox button{cursor:pointer}.seller-inbox button:disabled{cursor:wait;opacity:.55}.seller-inbox :is(a,button,input,textarea,[tabindex]):focus-visible{outline:2px solid #1f6f5b;outline-offset:2px}.inbox-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.inbox-sidebar{display:grid;grid-template-rows:auto minmax(0,1fr) auto;min-height:0;border-right:1px solid #e3ebe6}.inbox-list-header{padding:19px 16px 13px;border-bottom:1px solid #edf1ef}.inbox-list-header h1{font-size:18px;font-weight:600;display:flex;gap:9px;align-items:center}.inbox-list-header h1>span{font-size:10px;background:#edf5f0;color:#1f6f5b;padding:3px 7px;border-radius:20px}.inbox-search{display:flex;align-items:center;margin:14px 0 12px;border:1px solid #dde6e1;border-radius:10px;overflow:hidden}.inbox-search input{width:100%;min-width:0;border:0;background:#f9fbfa;padding:11px;font-size:12px}.inbox-search button{padding:10px;border:0;background:#f9fbfa;color:#52635b}.inbox-search svg{width:16px;height:16px}.inbox-filters{display:flex;flex-wrap:wrap;gap:5px}.inbox-filters a{padding:6px 8px;border-radius:7px;font-size:10px;color:#728078;white-space:nowrap}.inbox-filters a[aria-current]{background:#173f35;color:white}.inbox-conversations{overflow-y:auto;min-height:0;overscroll-behavior:contain}.inbox-row{display:flex;gap:10px;padding:14px 14px;border-bottom:1px solid #edf1ef;border-left:3px solid transparent;color:inherit}.inbox-row:hover{background:#f6faf7}.inbox-row.is-selected{background:#eef6f1;border-left-color:#1f6f5b}.inbox-avatar{width:38px;height:38px;flex-shrink:0;display:grid;place-items:center;border-radius:12px;background:#dff1e9;color:#173f35;font-size:14px;font-weight:600}.inbox-row-content{display:block;min-width:0;flex:1}.inbox-row-heading{display:flex;align-items:center;gap:6px;justify-content:space-between}.inbox-row-heading strong{font-size:12px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.inbox-row-heading time{flex-shrink:0;color:#98a59e;font-size:9px}.inbox-row-context,.inbox-row-preview{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#8a9790;font-size:10px;margin-top:4px}.inbox-row-preview{color:#728078;font-size:11px;margin-top:6px}.inbox-row.is-unread .inbox-row-heading strong,.inbox-row.is-unread .inbox-row-preview{font-weight:600;color:#173f35}.inbox-row-bottom{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px}.inbox-type{display:inline-block;border-radius:20px;background:#eff5f1;padding:3px 8px;color:#667d70;font-size:9px;white-space:nowrap}.inbox-unread{display:grid;place-items:center;min-width:19px;height:19px;padding:0 5px;background:#1f6f5b;color:white;border-radius:20px;font-size:9px;font-weight:600}.inbox-list-empty{padding:36px 20px;text-align:center}.inbox-list-empty h2{font-size:13px;font-weight:600}.inbox-list-empty p,.inbox-selection p{margin-top:6px;font-size:12px;color:#839189;line-height:1.7}.inbox-list-empty a{display:inline-block;margin-top:14px;font-size:11px;color:#1f6f5b}.inbox-list-pagination{padding:12px;border-top:1px solid #edf1ef;font-size:10px}.inbox-selection{display:grid;place-items:center;text-align:center;background:#f8fbf9;padding:20px}.inbox-selection svg{width:36px;height:36px;margin:0 auto 15px;color:#9eb9aa}.inbox-selection h2{font-size:17px;font-weight:600}.inbox-thread{position:relative;display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden}.inbox-thread-header{display:flex;align-items:center;gap:11px;padding:17px 20px;border-bottom:1px solid #e3ebe6;flex-shrink:0}.inbox-thread-identity{flex:1;min-width:0}.inbox-thread-identity h2{font-size:14px;font-weight:600;overflow-wrap:anywhere}.inbox-thread-identity p{margin-top:3px;font-size:10px;color:#839189;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.inbox-thread-identity a{font-size:10px;color:#1f6f5b}.inbox-thread-badges{display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end;max-width:140px}.inbox-status{font-size:9px;color:#1f6f5b;border:1px solid #d7e7dd;border-radius:20px;padding:3px 8px}.inbox-back{display:none}.inbox-history{flex:1;min-height:0;overflow-y:auto;background:#f7faf8;padding:12px 24px 22px;overscroll-behavior:contain;overflow-anchor:none}.inbox-older{text-align:center}.inbox-older button{font-size:10px;border:1px solid #dde6e1;border-radius:20px;padding:6px 12px;background:#fff;color:#1f6f5b}.inbox-older span{display:block;font-size:10px;color:#839189}.inbox-date{display:flex;align-items:center;justify-content:center;margin:18px 0;color:#91a096;font-size:10px}.inbox-message{display:flex;justify-content:flex-start;margin-top:14px;min-width:0}.inbox-message.is-mine{justify-content:flex-end}.inbox-message.is-grouped{margin-top:5px}.inbox-bubble{max-width:73%;min-width:65px;padding:11px 14px;border:1px solid #e0e9e3;border-radius:14px;background:white;color:#34473d}.is-mine>.inbox-bubble{background:#173f35;border-color:#173f35;color:white} .inbox-sender{display:flex;flex-wrap:wrap;gap:6px;font-size:10px;color:#667b6d;margin-bottom:5px}.is-mine .inbox-sender{color:#c1d9cb}.inbox-sender strong{font-weight:600}.is-grouped .inbox-sender{display:none}.inbox-bubble p{font-size:13px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}.inbox-bubble time{display:block;text-align:right;font-size:9px;color:#6f7e75;margin-top:6px}.is-mine .inbox-bubble time{color:#bdd1c4}.inbox-thread-empty{padding:60px 15px;text-align:center;font-size:12px;color:#839189}.inbox-composer{flex-shrink:0;padding:14px 18px;border-top:1px solid #e3ebe6;background:white}.seller-inbox #inboxBody{box-sizing:border-box;flex:1;min-width:0;resize:none;overflow-x:hidden;overflow-y:hidden;height:44px;min-height:44px;max-height:124px;border:1px solid #dde6e1;border-radius:11px;padding:11px 13px;font-size:13px;line-height:20px}.inbox-composer button[type=submit]{display:flex;align-items:center;gap:7px;border:0;border-radius:11px;background:#173f35;color:white;padding:12px 16px;font-size:12px;font-weight:600;min-height:44px;flex-shrink:0}.inbox-composer button svg{width:15px;height:15px}.inbox-composer noscript p{font-size:10px;color:#839189;margin-top:6px}.seller-inbox .inbox-error{font-size:11px;color:#a04435;margin:6px 0}.inbox-feedback,.inbox-closed{font-size:11px;color:#52635b;margin-bottom:8px!important}.inbox-notice{display:flex;gap:12px;padding:8px 16px;background:#fff7e8;font-size:10px;color:#856627;flex-shrink:0}.inbox-notice button{font:inherit;text-decoration:underline;border:0;background:none}.inbox-new-messages{position:absolute;bottom:90px;right:24px;border:1px solid #c8ddcf;border-radius:20px;background:#fff;color:#1f6f5b;box-shadow:0 3px 12px #173f3515;padding:7px 12px;font-size:11px}
@media(max-width:1100px){.seller-inbox{grid-template-columns:320px minmax(0,1fr)}.inbox-thread-header{padding:14px}.inbox-history{padding-left:15px;padding-right:15px}.inbox-bubble{max-width:85%}}
@media(max-width:800px){.seller-inbox{grid-template-columns:minmax(0,1fr);border-radius:12px;min-height:160px}.seller-inbox:not(.has-thread) .inbox-selection,.seller-inbox.has-thread .inbox-sidebar{display:none}.inbox-sidebar{border:0}.inbox-back{display:grid;place-items:center;width:44px;height:44px;margin-left:-8px;color:#1f6f5b;flex-shrink:0}.inbox-back svg{width:18px;height:18px}.inbox-thread-badges{max-width:105px}.inbox-thread-header>.inbox-avatar{width:32px;height:32px}.inbox-thread-identity h2{font-size:13px}.inbox-composer{padding:10px}.inbox-composer button[type=submit]{padding:12px}.inbox-bubble{max-width:88%}}
</style>
